nt TickInterval is '{currTickInterval}' seconds"); return; } if (arg.Args != null && arg.Args.Length >0) { float input = 0f; if (float.TryParse(arg.Args[0], out input)) { currTickInterval = input; SendReply(arg, $"TickInterval set to '{currTickInterval}' seconds"); _handler.TickInterval = currTickInterval; if (currTickInterval != tickInterval) { tickInterval = currTickInterval; Config["Handler", "tickInterval"] = tickInterval; Config.Save(); } return; } else { SendReply(arg, "You need to provide a full number in seconds"); return; } } }  [ConsoleCommand("sc.fill")] void ccmdSpawnFill(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; string populationname = string.Empty; bool single = false; if (arg.Args != null && arg.Args.Length >0) { populationname = arg.Args[0]; single = true; } Global.Runner.StartCoroutine(SpawnFill(populationname, single, arg)); }  IEnumerator SpawnFill(string populationname, bool single, ConsoleSystem.Arg arg) { runningSpawnFill = true; yield return new WaitWhile(new System.Func<bool>(() => runningEnforceLimits)); var allSpawnPopulations = (_AllSpawnPopulations.GetValue(_Handle) as SpawnPopulation[]).ToList().Where(x => x != null).ToArray(); bool findany = false; if (single) { bool fullMatch = false; SpawnDistribution[] spawndists =  (SpawnDistribution[])_SpawnDistributions.GetValue(_Handle); for (int i = 0; i < allSpawnPopulations.Length; i++) { if (!(allSpawnPopulations[i] == null)) { if ((allSpawnPopulations[i].name.StartsWith(populationname) || allSpawnPopulations[i].name.EndsWith(populationname)) && !fullMatch) { if (allSpawnPopulations[i].name == populationname) fullMatch = true; int oldCount = _Handle.GetCurrentCount(allSpawnPopulations[i], spawndists[i]); _Handle.SpawnInitial(allSpawnPopulations[i], spawndists[i]); if (arg.Args.Length > 1 && arg.Args[1] == "auto") if (logJobsToConsole) SendReply(arg, $"Timed population of '{allSpawnPopulations[i].name}' | Old: {oldCount} | New: {_Handle.GetCurr