 type }; NextTick(() => ccmdSpawnFill(arg)); } } else { SendReply(arg, $"Raising all SpawnPopulation density's by '{percentage}' percent"); for (int i = 0; i < allSpawnPopulations.Length; i++) { if (!(allSpawnPopulations[i] == null)) { float oldDensity = allSpawnPopulations[i].TargetDensity; float increaseDensity = allSpawnPopulations[i].TargetDensity / 100 * percentage; float newDensity = (float)Math.Round((double)(oldDensity+increaseDensity)); _targetDensity.SetValue(allSpawnPopulations[i], newDensity); SetAnimal(allSpawnPopulations[i].name, newDensity); (spawnPopulations[allSpawnPopulations[i].name] as Dictionary<string,object>)["spawndensity"] = allSpawnPopulations[i].TargetDensity; } } SendReply(arg, "New raised density's set and saved."); Config["Spawn", "Population"] = spawnPopulations; Config.Save(); arg.Args = null; NextTick(() => ccmdSpawnFill(arg)); } runningSpawnRaiseDensity = false; filter = Oxide.Game.Rust.RustExtension.Filter.ToList(); filter.Remove("Failed to create agent because there is no valid NavMesh"); Oxide.Game.Rust.RustExtension.Filter = filter.ToArray(); yield return null; }  [ConsoleCommand("sc.lowerdensity")] void ccmdSpawnLowerDensity(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; float percentage = 0f; string populationname = string.Empty; if (arg.Args == null || arg.Args.Length < 2) { SendReply(arg, "You need to provide a percentage number and a valid SpawnPopulation name"); return; } float percent = -1; if (float.TryParse(arg.Args[0], out percent)) percentage = percent; else { SendReply(arg, "You need to provide a number as percentage"); return; } populationname = arg.Args[1]; bool lowerAll = false; if (populationname == "all") lowerAll = true; if (percentage > 100f) { percentage = 100f; SendReply(arg, "Percentage was limited to 100%"); } bool force = false; if (arg.Args.Length >= 3 && arg.Args[2] == "force") force = true; if (lowerAll && percentage == 100f && !force) { SendReply(arg, "Canceled: Lowering all by 100% would set all to zero pop"); SendReply(arg, "You need to add 'force' as additional argument!"); return; } SendReply(arg, $"Calling lower with '{percentage}' percent for '{populationname}'"); Global.Runner.StartCoroutine(SpawnLowerDensity(percentage, populationname, lowerAll, arg)); }  IEnumerator SpawnLowerDensity(float percentage, string populationname, bool lowerAll, ConsoleSystem.Arg arg) { runningSpawnLowerDensity = true; var allSpawnPopulations = (_AllSpawnPopulations.GetValue(_Handle) as SpawnPopulation[]).ToList().Where(x => x != null).ToArray(); var filter = Oxide.Game.Rust.RustExtension.Filter.ToList(); filter.Add("Failed to create agent because there is no valid NavMesh"); Oxide.Game.Rust.RustExtension.Filter = filter.ToArray(); bool findany = false; if (!lowerAll) { bool fullMatch = false; for (int i = 0; i < allSpawnPopulations.Length; i++) { if (!(allSpawnPopulations[i] == null)) { if ((allSpawnPopulations[i].name.StartsWith(populationname) || allSpawnPopulations[i].name.EndsWith(populationname)) && !fullMatch) { if (allSpawnPopulations[i].name == populationname) fullMatch = true; float oldDensity = allSpawnPopulations[i].TargetDensity; float decreaseDensity = allSpawnPopulations[i].TargetDensity / 100 * percentage; float newDensity = -1f; if (percentage == 100f) newDensity = 0f; else newDensity = (float)Math.Round((double)(oldDensity-decreaseDensity)); _targetDensity.SetValue(allSpawnPopulations[i], newDensity); SetAnimal(allSpawnPopulations[i].name, newDensity); (spawnPopulations[allSpawnPopulations[i].name] as Dictionary<string,object>)["spawndensity"] = allSpawnPopulations[i].TargetDensity; SendReply(arg, $"Lowered density of '{allSpawnPopulations[i].name}' | Old: {oldDensity} | New: {newDensity}"); findany = true; } } } if (!findany) SendReply(arg, $"SpawnPopulation '{populationname}' not found"); else { SendReply(arg, $"New lowered density's set and saved."); Config["Spawn", "Population"] = spawnPopulations; Config.Save(