ns.GetValue(_Handle); bool findany = false; int countDeleted = 0; bool fullMatch = false; bool junkPiles = false; for (int i = 0; i < spawnpops.Length; i++) { if (!(spawnpops[i] == null)) { if ((spawnpops[i].name.StartsWith(populationname) || (spawnpops[i].name.EndsWith(populationname)) && !fullMatch) || killAll) { if (spawnpops[i].name == populationname) fullMatch = true; Spawnable[] array = _Handle.FindAll(spawnpops[i]); int count = array.Length; foreach (Spawnable current in array) { BaseEntity baseEntity = current.gameObject.ToBaseEntity(); if (baseEntity.IsValid()) { if (baseEntity is JunkPile) { (baseEntity as JunkPile).SinkAndDestroy(); junkPiles = true; } else { if (baseEntity is OreResourceEntity) (baseEntity as OreResourceEntity).CleanupBonus(); baseEntity.Kill(BaseNetworkable.DestroyMode.None); } countDeleted++; } else { GameManager.Destroy(current.gameObject, 0f); countDeleted++; } } if (!killAll) { if (junkPiles) SendReply(arg, $"Forced deletion of '{spawnpops[i].name}' | Old: {count} | New: {_Handle.GetCurrentCount(spawnpops[i], spawndists[i])}(DELAYED)"); else SendReply(arg, $"Forced deletion of '{spawnpops[i].name}' | Old: {count} | New: {_Handle.GetCurrentCount(spawnpops[i], spawndists[i] )}"); } findany = true; yield return new WaitForEndOfFrame(); } } } if (!findany && !killAll) SendReply(arg, $"SpawnPopulation '{populationname}' not found"); if (findany && killAll) { _Handle.UpdateDistributions(); SendReply(arg, $"SapwnHandler cleaned the map of '{countDeleted}' objects"); } runningSpawnKill = false; yield return null; }  [ConsoleCommand("sc.enforcelimits")] void ccmdEnforceLimits(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; bool forceAll = false; if (arg.Args != null && arg.Args.Length > 0) { if (arg.Args[0].ToLower() == "all") forceAll = true; } SendReply(arg, $"Enforcing population limits"); NextTick(()=> Global.Runner.StartCoroutine(EnforceLimits(forceAll, arg))); }  IEnumerator EnforceLimits(boo