xtTable.AddColumn("Limiting"); if (enablePopulationPrefabs) textTable.AddColumn("Prefabs"); for (int i = 0; i < allSpawnPopulations.Length; i++) { if (!(allSpawnPopulations[i] == null)) { SpawnPopulation spawnPopulation = allSpawnPopulations[i]; if (enablePopulationPrefabs) { var prefabs = spawnPopulation.Prefabs; textTable.AddRow(new string[] { spawnPopulation.name.ToString(), spawnPopulation.TargetDensity.ToString(), spawnPopulation.SpawnRate.ToString(), spawnPopulation.EnforcePopulationLimits.ToString(), prefabs.Length.ToString() }); } else textTable.AddRow(new string[] { spawnPopulation.name.ToString(), spawnPopulation.TargetDensity.ToString(), spawnPopulation.SpawnRate.ToString(), spawnPopulation.EnforcePopulationLimits.ToString() }); } } SendReply(arg, "\n>> SpawnPopulations:\n"+textTable.ToString()); }); }  [ConsoleCommand("sc.restoredensitys")] void ccmdRestoreDensitys(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; NextFrame(()=> { var allSpawnPopulations = (_AllSpawnPopulations.GetValue(_Handle) as SpawnPopulation[]).ToList().Where(x => x != null).ToArray(); if (spawnDefaults == null || spawnDefaults.Count == 0) { spawnDefaults = new Dictionary<string, object>(); defaultSpawnPops = getFile($"{this.Title}_defaults"); spawnDefaults = defaultSpawnPops["Backup"] as Dictionary<string, object>; } if (spawnDefaults == null || spawnDefaults.Count == 0) { SendReply(arg, "Default SpawnPopulations not found or file missing."); return; } for (int i = 0; i < allSpawnPopulations.Length; i++) { if (!(allSpawnPopulations[i] == null)) { var name = allSpawnPopulations[i].name; float newDensity = Convert.ToSingle(spawnDefaults[name]); _targetDensity.SetValue(allSpawnPopulations[i], newDensity); SetAnimal(name, newDensity); (spawnPopulations[allSpawnPopulations[i].name] as Dictionary<string,object>)["spawndensity"] = newDensity; } } Config["Spawn", "Population"] = spawnPopulations; Config.Save(); SendReply(arg, "Reverted SpawnPopulation density's to their defaults"); NextTick(() => { ccmdEnforceLimits(arg); ccmdSpawnFill(arg); }); }); }  [ConsoleCommand("sc.restoreweights")] void ccmdRestoreWeights(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; NextFrame(()=> { var allSpawnPopulations = (_AllSpawnPopulations.GetValue(_Handle) as SpawnPopulation[]).ToList().Where(x => x != null).ToArray(); if (spawnPrefabDefaults == null || spawnPrefabDefaults.Count == 0) { spawnPrefabDefaults = new Dictionary<string, object>(); defaultSpawnPops = getFile($"{this.Title}_defaults"); spawnPrefabDefaults = defaultSpawnPops["PrefabBackup"] as Dictionary<string, object>; } if (spawnPrefabDefaults == null || spawnPrefabDefaults.Count == 0) { SendReply(arg, "Default SpawnPopulationWeights not found or file missing."); return; } for (int i = 0; i < allSpawnPopulations.Length; i++) { if (!(allSpawnPopulations[i] == null)) { Dictionary<string,object> prefabData = spawnPrefabDefaults[allSpawnPopulations[i].name] as Dictionary<string,object>; var prefabs = new List<Prefab<Spawnable>>(); foreach (var prefab in prefabData) { var gameObject = GameManager.server.FindPrefab(prefab.Key); var component = gameObject?.GetComponent<Spawnable>(); if (component == null) continue; for (int j = 0; j < Convert.ToInt32(prefab.Value); j++) prefabs.Add(new Prefab<Spawnable>(prefab.Key.ToLower(), gameObject, component, GameManager.server, PrefabAttribute.server)); } allSpawnPopulations[i].Prefabs = prefabs.ToArray(); _numToSpawn.SetValue(allSpawnPopulations[i], new int[prefabs.ToArray().Length]); (spawnPopulations[allSpawnPopulations[i].name] as Dictionary<string,object>)["spawnweights"] = prefabData; } } Config["Spawn", "Population"] = spawnPopulations; Config.Save(); SendReply(arg, "Reverted SpawnPopulation weights's to their defaults. Probably 'kill all' is needed."); NextTick(() => { ccmdEnforceLimits(arg); ccmdSpawnFill(arg); }); }); }  [ConsoleCommand("sc.groupspawners")] void ccmdGetSpanwers(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; if (!enableSpawnGroups) { SendReply(arg, $"Command inactive. spawnGroups not activated"); return; } NextFrame(()=> { string filterTxt = string.Empty; if (arg.Args != null && arg.Args.Length > 0) filterTxt = arg.Args[0]; TextTable textTable = new TextTable(); textTable.AddColumn("Name"); if (enableGroupTickData) textTable.AddColumn("MaxObj"); textTable.AddColumn("Respawn (s)"); if (enableGroupTickData) textTable.AddColumn("perTick"); textTable.AddColumn("Monument"); List<string>monumentnames = new List<string>(); foreach (var monument in UnityEngine.Object.FindObjectsOfType<MonumentInfo>()) { if (monumentnames.Contains(monument.name)) continue; monumentnames.Add(monument.name); List<string>groupnames = new List<string>(); foreach(var group in monument.gameObject.GetComponentsInChildren<SpawnGroup>()) { if (!string.IsNullOrEmpty(filterTxt) && !PrefabCut(monument.name).Contains(filterTxt)) continue; if (groupnames.Contains(group.name)) continue; if (group.name.StartsWith("door_barricade") || group.name.StartsWith("Barricades") || group.name.StartsWith("Ore")) continue; groupnames.Add(group.name); if (enableGroupTickData) textTable.AddRow(new string[] { group.name.ToString(), group.maxPopulation.ToString(), $"{group.respawnDelayMin} - {group.respawnDelayMax}", $"{group.numToSpawnPerTickMin} - {group.numToSpawnPerTickMax}", PrefabCut(monument.name) }); else textTable.AddRow(new string[] { group.name.ToString(), $"{group.respawnDelayMin} - {group.respawnDelayMax}", PrefabCut(monument.name) }); } } SendReply(arg, "\n>> GroupSpawners:\n"+textTable.ToString()); }); }  [ConsoleCommand("sc.dumpresources")] void ccmdDumpResources(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; NextFrame(()=> { TextTable textTable = new TextTable(); textTable.AddColumn("Name"); textTable.AddColumn("Count"); textTable.AddColumn("Type"); foreach (var t in GetCollectibles()) textTable.AddRow(new string[] { t.Key.ToString(), t.Value.ToString(), "Collectible" }); foreach (var t in GetOreNodes()) textTable.AddRow(new string[] { t.Key.ToString(), t.Value.Count().ToString(), "Ore" }); foreach (var t in GetAnimals()) textTable.AddRow(new string[] { t.Key.ToString(), t.Value.Count().ToString(), "Animals" }); SendReply(arg, "\n>> Resources:\n"+textTable.ToString()); }); }  [ConsoleCommand("sc.dumploot")] void ccmdDumpLoot(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; NextFrame(()=> { TextTable textTable = new TextTable(); textTable.AddColumn("Name"); textTable.AddColumn("Count"); textTable.AddColumn("Type"); foreach (var t in GetLootContainers()) textTable.AddRow(new string[] { t.Key.ToString(), t.Value.Count().ToString(), "Loot" }); SendReply(arg, "\n>> Loot:\n"+textTable.ToString()); }); }  [ConsoleCommand("sc.cmds")] void ccmdComandsList(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < 2) return; var sb = new StringBuilder(); sb.AppendLine("\n==== Command List ================\n"); sb.AppendLine($"sc.cleardata".PadRight(21) + "| Clear Population and/or Group data by 'all', 'population' or 'groups"); sb.AppendLine($"sc.tickinterval".PadRight(21) + "| Show or set the Population tick interval in 'seconds'"); sb.AppendLine($"sc.fill".PadRight(21) + "| Fill all Populations or choosen one's by 'filter'"); sb.AppendLine($"sc.kill".PadRight(21) + "| Kill 'all' Populations or choosen one's by 'filter'"); sb.AppendLine($"sc.raisedensity".PadRight(21) + "| Raise Populations in 'percent' for 'all' or choosen one's by 'filter'"); sb.AppendLine($"sc.lowerdensity".PadRight(21) + "| Lower Populations in 'percent' for 'all' or choosen one's by 'filter'"); sb.AppendLine($"sc.enforcelimits".PadRight(21) + "| Enforce object limits on all Populations"); sb.AppendLine($"sc.reload".PadRight(21) + "| Reload the plugin after config changes"); sb.AppendLine($"sc.report".PadRight(21) + "| Display current Population objects with their limits"); sb.AppendLine($"sc.spawnpopulations".PadRight(21) + "| Display current Population settings"); sb.AppendLine($"sc.restoredensitys".PadRight(21) + "| Restore Population densitys to their defaults"); sb.AppendLine($"sc.restoreweights".PadRight(21) + "| Restore Population weights to their defaults"); sb.AppendLine($"sc.groupspawners".PadRight(21) + "| Display SpawnGroup timers"); sb.AppendLine($"sc.dumpresources".PadRight(21) + "| Dump current resource amount"); sb.AppendLine($"sc.dumploot".PadRight(21) + "| Dump current complete loot amount (Populations and Groups)"); sb.AppendLine($"sc.cmds".PadRight(21) + "| Show this command"); sb.AppendLine($"sc.showconfig".PadRight(21) + "| Show current config options"); SendReply(arg, sb.ToString()); }  [ConsoleCommand("sc.showconfig")] void cmdShowConfig(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < 2) return; var sb = new StringBuilder(); sb.AppendLine("\n==== Current config options ================\n"); sb.AppendLine($"enableSpawnGroups".PadRight(26) + "| Loading and usage of spawnGroups (optional)> "+ enableSpawnGroups); sb.AppendLine($"enableGroupTickData".PadRight(26) + "| Usage of spawnGroups spawn per tick data (optional) > "+ enableGroupTickData); sb.AppendLine($"enablePopulationPrefabs".PadRight(26) + "| Loading and usage of SpawnPopulation prefabs (optional) > "+ enablePopulationPrefabs); sb.AppendLine($"normalizeDefaultVariables".PadRight(26) + "| Reverts server 'spawn' variables to defaults (recommended) > "+ normalizeDefaultVariables); sb.AppendLine($"reloadWithIncludedFill".PadRight(26) + "| Would also fill population after running 'sc.reload' > "+ reloadWithIncludedFill); sb.AppendLine($"logJobsToConsole".PadRight(26) + "| Would show 'spawnfillheartbeat' jobs in console > "+ logJobsToConsole); sb.AppendLine($"fixBarricadeStacking".PadRight(26) + "| Prevents stacking of doorbarricades > "+ fixBarricadeStacking); sb.AppendLine($"tickInterval".PadRight(26) + "| Interval between each population attempt (default 60) > "+ tickInterval); sb.AppendLine($"minSpawnsPerTick".PadRight(26) + "| Minimum objects to spawn per tick (default 100) > "+ minSpawnsPerTick); sb.AppendLine($"maxSpawnsPerTick".PadRight(26) + "| Maximum objects to spawn per tick (default 100) > "+ maxSpawnsPerTick); SendReply(arg, sb.ToString()); }  Dictionary<string, int> GetCollectibles() => Resources.FindObjectsOfTypeAll<CollectibleEntity>().Where(c => c.isActiveAndEnabled && !c.ShortPrefabName.Contains("mushroom")).GroupBy(c => c.ShortPrefabName).ToDictionary(c => c.Key.Remove(c.Key.Length - 12), c => c.Count()); Dictionary<string, IGrouping<string, BaseEntity>> GetOreNodes() => Resources.FindObjectsOfTypeAll<ResourceEntity>().Where(c => c.name.Contains("-ore") && c.isActiveAndEnabled).Cast<BaseEntity>().GroupBy(c => c.ShortPrefabName).ToDictionary(c => c.Key, c => c); Dictionary<string, IGrouping<string, BaseEntity>> GetLootContainers() => Resources.FindObjectsOfTypeAll<LootContainer>().Where(c => c.isActiveAndEnabled).Cast<BaseEntity>().GroupBy(c => c.ShortPrefabName).ToDictionary(c => c.Key, c => c); Dictionary<string, IGrouping<string, BaseEntity>> GetAnimals() =>Resources.FindObjectsOfTypeAll<BaseNpc>().Where(c => c.isActiveAndEnabled).Cast<BaseEntity>().GroupBy(c => c.ShortPrefabName).ToDictionary(c => c.Key, c => c); string PrefabCut(string name) => Oxide.Core.ExtensionMethods.Basename(name, ".prefab"); } }
